 265→+	}
 266→+
 267→+	req.Header.Set("Accept", "application/json")
 268→+	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
 269→+	req.Header.Set("User-Agent", "entire-cli")
 270→+
 271→+	resp, err := c.httpClient.Do(req) //nolint:gosec // base URL is constrained to Entire API or explicit local dev override
 272→+	if err != nil {
 273→+		return nil, fmt.Errorf("poll device auth: %w", err)
 274→+	}
 275→+	defer resp.Body.Close()
 276→+
 277→+	if resp.StatusCode != http.StatusOK {
 278→+		apiErr, err := readAPIErrorResponse(resp)
 279→+		if err != nil {
 280→+			return nil, fmt.Errorf("poll device auth: %w", err)
 281→+		}
 282→+		return &DeviceAuthPoll{Error: apiErr.Error}, nil
 283→+	}
 284→+
 285→+	var result DeviceAuthPoll
 286→+	if err := decodeJSON(resp.Body, &result); err != nil {
 287→+		return nil, fmt.Errorf("decode device auth poll response: %w", err)
 288→+	}
 289→+
 290→+	return &result, nil
 291→+}
 292→+
 293→+func readAPIErrorResponse(resp *http.Response) (*errorResponse, error) {
 294→+	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
 295→+	if err != nil {
 296→+		return nil, fmt.Errorf("status %d", resp.StatusCode)
 297→+	}
 298→+
 299→+	var apiErr errorResponse
 300→+	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
 301→+		return &apiErr, nil
 302→+	}
 303→+
 304→+	text := strings.TrimSpace(string(body))
 305→+	if text != "" {
 306→+		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, text)
 307→+	}
 308→+
 309→+	return nil, fmt.Errorf("status %d", resp.StatusCode)
 310→+}
 311→+
 312→+func readAPIError(resp *http.Response, action string) error {
 313→+	apiErr, err := readAPIErrorResponse(resp)
 314→+	if err == nil {
 315→+		return fmt.Errorf("%s: %s", action, apiErr.Error)
 316→+	}
 317→+	return fmt.Errorf("%s: %w", action, err)
 318→+}
 319→+
 320→+func decodeJSON(r io.Reader, dest any) error {
 321→+	return decodeJSONWithOptions(r, dest, false)
 322→+}
 323→+
 324→+func decodeJSONStrict(r io.Reader, dest any) error {
 325→+	return decodeJSONWithOptions(r, dest, true)
 326→+}
 327→+
 328→+func decodeJSONWithOptions(r io.Reader, dest any, strict bool) error {
 329→+	body, err := io.ReadAll(io.LimitReader(r, maxResponseBytes))
 330→+	if err != nil {
 331→+		return fmt.Errorf("read JSON response: %w", err)
 332→+	}
 333→+
 334→+	dec := json.NewDecoder(bytes.NewReader(body))
 335→+	if strict {
 336→+		dec.DisallowUnknownFields()
 337→+	}
 338→+	if err := dec.Decode(dest); err != nil {
 339→+		return fmt.Errorf("decode JSON response: %w", err)
 340→+	}
 341→+
 342→+	return nil
 343→+}
