 443→+func (s *Store) SaveToken(baseURL, token string) error {
 444→+	state, err := s.Load()
 445→+	if err != nil {
 446→+		return err
 447→+	}
 448→+
 449→+	if state.Tokens == nil {
 450→+		state.Tokens = make(map[string]Token)
 451→+	}
 452→+
 453→+	state.Tokens[baseURL] = Token{
 454→+		Value:     token,
 455→+		CreatedAt: time.Now().UTC().Format(time.RFC3339),
 456→+	}
 457→+
 458→+	return s.save(state)
 459→+}
 460→+
 461→+func (s *Store) Load() (*File, error) {
 462→+	data, err := os.ReadFile(s.filePath)
 463→+	if err != nil {
 464→+		if os.IsNotExist(err) {
 465→+			return &File{}, nil
 466→+		}
 467→+		return nil, fmt.Errorf("read auth file: %w", err)
 468→+	}
 469→+
 470→+	var state File
 471→+	if err := json.Unmarshal(data, &state); err != nil {
 472→+		return nil, fmt.Errorf("parse auth file: %w", err)
 473→+	}
 474→+
 475→+	return &state, nil
 476→+}
 477→+
 478→+func defaultFilePath() (string, error) {
 479→+	home, err := os.UserHomeDir()
 480→+	if err != nil {
 481→+		return "", fmt.Errorf("get home directory: %w", err)
 482→+	}
 483→+
 484→+	return filepath.Join(home, ".config", "entire", authFileName), nil
 485→+}
 486→+
 487→+func (s *Store) save(state *File) error {
 488→+	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 489→+	if err != nil {
 490→+		return fmt.Errorf("marshal auth file: %w", err)
 491→+	}
 492→+
 493→+	dir := filepath.Dir(s.filePath)
 494→+	if err := os.MkdirAll(dir, 0o700); err != nil {
 495→+		return fmt.Errorf("create auth directory: %w", err)
 496→+	}
 497→+
 498→+	tmpFile, err := os.CreateTemp(dir, ".auth_tmp_")
 499→+	if err != nil {
 500→+		return fmt.Errorf("create temp auth file: %w", err)
 501→+	}
 502→+	defer os.Remove(tmpFile.Name())
 503→+
 504→+	if err := tmpFile.Chmod(0o600); err != nil {
 505→+		_ = tmpFile.Close()
 506→+		return fmt.Errorf("set temp auth permissions: %w", err)
 507→+	}
 508→+
 509→+	if _, err := tmpFile.Write(data); err != nil {
 510→+		_ = tmpFile.Close()
 511→+		return fmt.Errorf("write temp auth file: %w", err)
 512→+	}
 513→+
 514→+	if err := tmpFile.Sync(); err != nil {
 515→+		_ = tmpFile.Close()
 516→+		return fmt.Errorf("sync temp auth file: %w", err)
 517→+	}
 518→+
 519→+	if err := tmpFile.Close(); err != nil {
 520→+		return fmt.Errorf("close temp auth file: %w", err)
 521→+	}
 522→+
 523→+	if err := os.Rename(tmpFile.Name(), s.filePath); err != nil { //nolint:gosec // destination path is internally constructed or test-controlled
 524→+		return fmt.Errorf("rename auth file: %w", err)
 525→+	}
 526→+
 527→+	return nil
 528→+}
 529→+
 530→+func LookupToken(state *File) string {
 531→+	if state == nil || state.Tokens == nil {
 532→+		return ""
 533→+	}
 534→+
 535→+	entry, ok := state.Tokens[apiurl.BaseURL()]
 536→+	if !ok {
 537→+		return ""
 538→+	}
 539→+
 540→+	return entry.Value
 541→+}
