 30→func newLoginCmd() *cobra.Command {
 31→	var printBrowserURL bool
 32→
 33→	cmd := &cobra.Command{
 34→		Use:   "login",
 35→		Short: "Log in to Entire",
 36→		RunE: func(cmd *cobra.Command, _ []string) error {
 37→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), printBrowserURL)
 38→		},
