 15→const authFileName = "auth.json"
 16→
 17→type Store struct {
 18→	filePath string
 19→}
 20→
 21→type File struct {
 22→	Tokens map[string]Token `json:"tokens,omitempty"`
 23→}
 24→
 25→type Token struct {
 26→	Value     string `json:"value"`
 27→	CreatedAt string `json:"created_at"`
 28→}
 29→
 30→func NewStore() (*Store, error) {
 31→	filePath, err := defaultFilePath()
 32→	if err != nil {
 33→		return nil, err
 34→	}
 35→
 36→	return &Store{filePath: filePath}, nil
 37→}
 38→
 39→func NewStoreForPath(filePath string) *Store {
 40→	return &Store{filePath: filePath}
 41→}
 42→
 43→func (s *Store) FilePath() string {
 44→	return s.filePath
 45→}
 46→
 47→func (s *Store) SaveToken(baseURL, token string) error {
 48→	if strings.TrimSpace(token) == "" {
 49→		return errors.New("refusing to save empty token")
 50→	}
 51→
 52→	state, err := s.Load()
 53→	if err != nil {
 54→		return err
 55→	}
 56→
 57→	if state.Tokens == nil {
 58→		state.Tokens = make(map[string]Token)
 59→	}
 60→
 61→	state.Tokens[baseURL] = Token{
 62→		Value:     token,
 63→		CreatedAt: time.Now().UTC().Format(time.RFC3339),
 64→	}
 65→
 66→	return s.save(state)
 67→}
 68→
 69→func (s *Store) Load() (*File, error) {
 70→	data, err := os.ReadFile(s.filePath)
 71→	if err != nil {
 72→		if os.IsNotExist(err) {
 73→			return &File{}, nil
 74→		}
 75→		return nil, fmt.Errorf("read auth file: %w", err)
 76→	}
 77→
 78→	var state File
 79→	if err := json.Unmarshal(data, &state); err != nil {
 80→		return nil, fmt.Errorf("parse auth file: %w", err)
 81→	}
 82→
 83→	return &state, nil
 84→}
 85→
 86→func defaultFilePath() (string, error) {
 87→	home, err := os.UserHomeDir()
 88→	if err != nil {
 89→		return "", fmt.Errorf("get home directory: %w", err)
 90→	}
 91→
 92→	return filepath.Join(home, ".config", "entire", authFileName), nil
 93→}
 94→
 95→func (s *Store) save(state *File) error {
 96→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 97→	if err != nil {
 98→		return fmt.Errorf("marshal auth file: %w", err)
 99→	}
100→
101→	dir := filepath.Dir(s.filePath)
102→	if err := os.MkdirAll(dir, 0o700); err != nil {
103→		return fmt.Errorf("create auth directory: %w", err)
104→	}
105→
106→	tmpPath := filepath.Join(dir, ".auth_tmp_"+strconv.FormatInt(time.Now().UnixNano(), 10))
107→	tmpFile, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600) //nolint:gosec // path is internally constructed from s.filePath
108→	if err != nil {
109→		return fmt.Errorf("create temp auth file: %w", err)
110→	}
111→	defer os.Remove(tmpFile.Name())
112→
113→	if _, err := tmpFile.Write(data); err != nil {
114→		_ = tmpFile.Close()
115→		return fmt.Errorf("write temp auth file: %w", err)
116→	}
117→
118→	if err := tmpFile.Sync(); err != nil {
119→		_ = tmpFile.Close()
120→		return fmt.Errorf("sync temp auth file: %w", err)
121→	}
122→
123→	if err := tmpFile.Close(); err != nil {
124→		return fmt.Errorf("close temp auth file: %w", err)
125→	}
126→
127→	if err := os.Rename(tmpFile.Name(), s.filePath); err != nil { //nolint:gosec // destination path is internally constructed or test-controlled
128→		return fmt.Errorf("rename auth file: %w", err)
129→	}
130→
131→	return nil
132→}
